// ============ CONFIG ÚNICA — Encaminhar O.S. por condomínio (5 bases) ============
const cfg = {
  // true = só mostra o que faria. Passe para false depois de conferir a simulação.
  SIMULAR: false,

  // Filtro "status != F" na consulta da API (evita trazer o histórico inteiro).
  // Se o diagnóstico "leitura" mostrar total 0 com O.S. abertas no IXC, troque para false.
  FILTRO_STATUS_NA_API: true,
    CONTINUIDADE: true,
  // Status de O.S. SEM técnico que o workflow encaminha.
  STATUS_PENDENTE: ['A', 'AG','RAG'],
  // Status que continuam iguais depois do encaminhamento (os demais viram EN).
  MANTER_STATUS: ['AG','RAG'],
   // Assuntos que o Encaminhar NUNCA mexe (documentação é do workflow de Documentação GLOBAL).
  // Saem da busca, da carga e do histórico da continuidade, mesmo que estejam em ASSUNTOS.
  EXCECAO_ASSUNTOS: {
    RESOLUTTO: [85],
    '4B':      [92],
    PONTO:     [64],
    CACTA:     [76],
    BUZZ:      [86],
  },

  // Assuntos de ativação por base.
  ASSUNTOS: {
    RESOLUTTO: [69, 83, 84, 86, 94, 14],
    '4B':      [89, 90, 91, 93, 98],
    PONTO:     [65, 63, 62, 61, 70],
    CACTA:     [73, 74, 77, 75, 81],
    BUZZ:      [83, 84, 85, 87, 91],
  },

  // Condomínio -> técnico(s) (id de colaborador DAQUELA base). Dois ou mais = menor carga na base.
  // Condomínio fora da tabela: a O.S. não é mexida.
  MAPA: {
    RESOLUTTO: {
      203: [36],        // CTA RESOLUTTO           -> Técnico 36
      209: [6],        // PATTEO URUPEMA          -> Técnico 6
      214: [12],       // UMUARAMA                -> Técnico 12
      208: [13],       // PONTAL                  -> Técnico 13
      219: [16],       // CIDADE DOS LAGOS        -> Técnico 16
      226: [17],       // PASSO FUNDO             -> Técnico 17
      217: [25, 18],   // PALLADIUM CURITIBA      -> Técnico 25 / Técnico 18
      225: [20],       // PÁTIO CHAPECÓ           -> Técnico 20
      227: [21],       // PORTO BELO              -> Técnico 21
      215: [22],       // PATO BRANCO             -> Técnico 22
      207: [31, 38],   // CATUAÍ CASCAVEL         -> Técnico 31 / Técnico 38
      221: [56],       // I FASHION TIJUCAS       -> Técnico 56
      216: [52],       // PÁTIO PETRÓPOLIS        -> Técnico 52
      212: [32, 54],   // JOCKEY PLAZA            -> Técnico 32 / Técnico 54
      228: [51],       // ITAJAÍ                  -> Técnico 51
      211: [35],       // MOGI MIRIM              -> Técnico 35
      222: [37],       // SINOP                   -> Técnico 37
      213: [25, 18],   // VENTURA                 -> Técnico 48
      206: [57],       // ESTAÇÃO                 -> Técnico 57
      218: [41],       // OUTLET CITY CENTER      -> Técnico 41
      204: [42],       // PLAZA CAMPOS GERAIS     -> Técnico 42
      205: [43],       // GRAVATAÍ                -> Técnico 43
      210: [44],       // SUMARE   -> Técnico 44 (?)
      220: [55, 45],   // CATUAÍ PALLADIUM FOZ    -> Técnico 55 / Técnico 45
    },
     '4B': {
      200: [25, 18],   // —   -> Técnico 25 / Técnico 18
      202: [12],       // —   -> Técnico 12
      276: [22],       // —   -> Técnico 22 ✔
      243: [46],       // —   -> Técnico 52 ✔
      199: [25, 18],   // —   -> Técnico 25 / Técnico 18
      244: [41],       // —   -> Técnico 41
      275: [16],       // —   -> Técnico 16
      201: [48, 45],   // —   -> Técnico 55  / Técnico 45
    },
    PONTO: {
      144: [62],       // —   -> Técnico 56
      216: [37],       // —   -> Técnico 37
      110: [59],       // —   -> Técnico 51 ✔
      273: [61],       // —   -> Técnico PONTO-61
      84:  [20],       // —   -> Técnico 20
      159: [17],       // —   -> Técnico 17
      134: [21],       // —   -> Técnico 21
      104: [59],       // —   -> Técnico 51 ✔
      49:  [20],       // —   -> Técnico 20
    },
    CACTA: {
      206: [13],       // —   -> Técnico 13
      247: [6],        // —   -> Técnico 6
      253: [44],       // —   -> Técnico 44
      248: [35],       // —   -> Técnico 35
      263: [32, 46],   // —   -> Técnico 32 / Técnico 54
      260: [38, 31],   // —   -> Técnico 38 / Técnico 31
    },
    BUZZ: {
      280: [42],       // —   -> Técnico 42 ✔
      271: [43],       // —   -> Técnico 43 ✔
      269: [46],       // —   -> Técnico 57
    },
  },
  // Condomínio -> id do SETOR daquela base (usado no encaminhamento junto com o técnico).
  // Condomínio sem setor aqui: mantém o setor atual da O.S. (ou pula, se SETOR_OBRIGATORIO = true).
  SETOR: {
    RESOLUTTO: { /* VENTURA */213:38,/* UMUARAMA */214:34,/* TIJUCAS */221:39,/* SINOP */222:44,/* RIVIERA */223:54,/* PULSE OPEN MALL */224:41,/* PONTAL */208:52,/* PLAZA CAMPOS GERAIS */204:45,/* PATTEO URUPEMA MOGI DAS CRUZES */209:51,/* PATO BRANCO */215:35,/* PATIO PETROPOLIS */216:37,/* PATIO CHAPECO */225:18,/* PASSO FUNDO */226:43,/* PARK CITY SUMARE */210:53,/* PALLADIUM CURITIBA */217:33,/* OUTLET PORTO BELO */227:40,/* OUTLET CITY CENTER */218:32, /* MOGI MIRIM */211:50,/* JOCKEY PLAZA */212:49,/* ITAJAI SHOPPING */228:42, /* GRAVATAI */205:47,/* ESTACAO CURITIBA */206:46, /* CIDADE DOS LAGOS */219:36,/* CATUAI PALLADIUM FOZ */220:31,/* CATUAI CASCAVEL */207:48,},
    '4B':      {/*CITY CENTER*/244:12, /*PALLADIUM CURITIBA*/199:11,/*PATO BRANCO*/276:16,
               /*CATUAI PALLADIUM*/201:14,/*CIDADE DOS LAGOS*/275:13,
                /*PETRÓPOLIS*/243:17,/*VENTURA*/200:18,/*PALLADIUM UMUARAMA*/202:15,},
    PONTO:     {/*PÁTIO CHAPECÓ*/84:18,/*PORTO BELO OUTLET*/134:19,
                /*I FASHION OUTLET TIJUCAS*/144:23,/*PULSE OPEN 
                MALL*/273:36,/*ITAJAI*/104:37, /*PASSO FUNDO*/159:17,/*SHOPPING SINOP*/216:25,/*RIVIEIRA BUSINESS*/110:43},
    CACTA:     {/*PARK CITY SUMARE*/253:13,/*PATTEO URUPEMA*/247:12,/*MOGI MIRIM*/248:10,
                /*CATUAI CASCAVEL*/260:15,/*JOCKEY PLAZA*/263:11,/*PONTAL SHOPPING*/206:14,},
    BUZZ:      {/*PLAZA CAMPOS GERAIS*/280:12,/*ESTAÇÃO*/269:11,/*GRAVATAI*/271:10,},
  },
  SETOR_OBRIGATORIO: false,


  // Status que contam como carga em aberto (desempate entre técnicos do mesmo condomínio).
  STATUS_CARGA: ['A', 'DS', 'AN', 'EX', 'EN', 'AS', 'RAG', 'AG'],
};
// ==================================================================================
// Remove os assuntos de exceção de ASSUNTOS (vale para busca, carga e continuidade).
for (const b of Object.keys(cfg.ASSUNTOS)) {
  const exc = ((cfg.EXCECAO_ASSUNTOS || {})[b] || []).map(String);
  cfg.ASSUNTOS[b] = cfg.ASSUNTOS[b].filter(a => !exc.includes(String(a)));
}
// Uma saída por posição de assunto: cada nó "OS <BASE>" consulta 1 assunto por item.
const n = Math.max(...Object.values(cfg.ASSUNTOS).map(a => a.length));
return Array.from({ length: n }, (_, i) => ({ json: { i, cfg } }));

// Junta as O.S. lidas (1 item por assunto em cada nó "OS <BASE>") e separa as pendentes.
const cfg = $('Config').first().json.cfg;
const BASES = Object.keys(cfg.ASSUNTOS);
function parseTolerante(v) {
  if (v && typeof v === 'object' && v.data === undefined) return v;
  const txt = v && typeof v === 'object' ? v.data : v;
  const limpo = String(txt || '').replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '');
  try { return JSON.parse(limpo); } catch (e) { return { erro: 'JSON inválido: ' + e.message }; }
}
const out = [];
for (const b of BASES) {
  const assuntos = cfg.ASSUNTOS[b].map(String);
  const vistos = new Set();
  $('OS ' + b).all().forEach((it, i) => {
    if (i >= assuntos.length) return;
    const r = parseTolerante(it.json);
    for (const os of (r.registros || [])) {
      if (vistos.has(os.id)) continue; vistos.add(os.id);
      const tec = String(os.id_tecnico || '0');
      if ((cfg.STATUS_PENDENTE || ['A']).includes(os.status) && (tec === '0' || tec === '') && assuntos.includes(String(os.id_assunto))) {
        out.push({ json: { base: b, id_chamado: Number(os.id), id_assunto: Number(os.id_assunto), id_cliente: Number(os.id_cliente || 0), setor: String(os.setor || ''), status: os.status } });
      }
    }
  });
}
if (!out.length) out.push({ json: { base: '', id_chamado: 0, id_cliente: 0, setor: '', vazio: true } });
return out;

// Decide o técnico de cada O.S. pendente. Configuração fica no nó "Config".
const cfg = $('Config').first().json.cfg;
const BASES = Object.keys(cfg.ASSUNTOS);
const SAIDA = Object.fromEntries(BASES.map((b, i) => [b, i])); // 5 = não encaminha
const NAO = BASES.length;

function parseTolerante(v) {
  if (v && typeof v === 'object' && v.data === undefined) return v;
  const txt = v && typeof v === 'object' ? v.data : v;
  const limpo = String(txt || '').replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '');
  try { return JSON.parse(limpo); } catch (e) { return { erro: 'JSON inválido: ' + e.message }; }
}
const falhou = r => r.erro || r.error || r.type === 'error';

// 1) Leitura, erros e carga por base
const leitura = {}, erroBase = {}, carga = {};
for (const b of BASES) {
  carga[b] = {};
  for (const tecs of Object.values(cfg.MAPA[b] || {})) for (const t of tecs) carga[b][String(t)] = 0;
  leitura[b] = { por_assunto: {}, por_status: {} };
  const vistos = new Set();
  $('OS ' + b).all().forEach((it, i) => {
    const a = cfg.ASSUNTOS[b][i];
    if (a === undefined) return;
    const r = parseTolerante(it.json);
    if (falhou(r)) { erroBase[b] = `assunto ${a}: ` + (r.erro || r.message || JSON.stringify(r.error)); return; }
    const regs = r.registros || [];
    leitura[b].por_assunto[a] = { total_api: r.total, registros: regs.length };
    if (!regs.length) leitura[b].por_assunto[a].inicio_resposta = String(it.json.data || '').slice(0, 200);
    for (const os of regs) {
      if (vistos.has(os.id)) continue; vistos.add(os.id);
      leitura[b].por_status[os.status] = (leitura[b].por_status[os.status] || 0) + 1;
      const t = String(os.id_tecnico);
      if (cfg.STATUS_CARGA.includes(os.status) && t in carga[b]) carga[b][t]++;
    }
  });
}
const cargaInicial = JSON.parse(JSON.stringify(carga));

// 2) Pendentes (condomínio vem dos nós "Cliente <BASE>", pareados por índice)
const pend = $('Pendentes').all();
const cli = {}; for (const b of BASES) cli[b] = $('Cliente ' + b).all();
const resumo = Object.fromEntries(BASES.map(b => [b, { pendentes: 0, encaminhar: 0, fora_da_tabela: 0, sem_cliente: 0, erro: erroBase[b] || null }]));
const saida = [];
const hist = {}; for (const b of BASES) hist[b] = $('Historico ' + b).all();
const daRodada = {}; // "base|cliente" -> técnico escolhido nesta rodada

pend.forEach((it, i) => {
  const p = it.json;
  if (p.vazio) return;
  const b = p.base;
  resumo[b].pendentes++;
  const base = { tipo: 'decisao', base: b, id_chamado: p.id_chamado, id_assunto: p.id_assunto, id_cliente: p.id_cliente };

  if (erroBase[b]) { saida.push({ json: { ...base, regra: 'base com erro de leitura — pulada', saida: NAO } }); return; }

  const rc = parseTolerante(cli[b][i] ? cli[b][i].json : null);
  const cliente = (rc.registros || [])[0];
  if (falhou(rc) || !cliente) { resumo[b].sem_cliente++; saida.push({ json: { ...base, regra: 'cliente não encontrado — não mexe', saida: NAO } }); return; }

  const cond = Number(cliente.id_condominio || 0);
  const tecs = (cfg.MAPA[b] || {})[cond];
  if (!tecs || !tecs.length) { resumo[b].fora_da_tabela++; saida.push({ json: { ...base, condominio: cond || null, regra: 'condomínio fora da tabela — não mexe', saida: NAO } }); return; }

    // Setor do condomínio (SETOR no Config). Sem setor configurado: mantém o da O.S. ou pula, conforme SETOR_OBRIGATORIO.
  const setorCfg = ((cfg.SETOR || {})[b] || {})[cond];
  if (!setorCfg && cfg.SETOR_OBRIGATORIO) { resumo[b].sem_setor = (resumo[b].sem_setor || 0) + 1; saida.push({ json: { ...base, condominio: cond, regra: 'condomínio sem setor no SETOR — não mexe', saida: NAO } }); return; }
  const idSetor = String(setorCfg || p.setor);

  let escolhido, regra, sorteio = [], anterior;
  const lista = tecs.map(String);
  if (tecs.length === 1) { escolhido = String(tecs[0]); regra = `condominio ${cond}`; }
  else if (cfg.CONTINUIDADE && daRodada[b + '|' + p.id_cliente] && lista.includes(daRodada[b + '|' + p.id_cliente])) {
    escolhido = daRodada[b + '|' + p.id_cliente];
    regra = `condominio ${cond} — continuidade (mesmo cliente nesta rodada)`;
  }
  else if (cfg.CONTINUIDADE && (anterior = (() => {
      // O.S. anterior do mesmo cliente, num dos assuntos da cadeia, com técnico da lista do condomínio (a mais recente).
      const rh = parseTolerante(hist[b][i] ? hist[b][i].json : null);
      const assuntos = cfg.ASSUNTOS[b].map(String);
      return (rh.registros || [])
        .filter(o => Number(o.id) !== p.id_chamado && assuntos.includes(String(o.id_assunto)) && lista.includes(String(o.id_tecnico)))
        .sort((x, y) => Number(y.id) - Number(x.id))[0];
    })())) {
    escolhido = String(anterior.id_tecnico);
    regra = `condominio ${cond} — continuidade (O.S. ${anterior.id}, assunto ${anterior.id_assunto}, status ${anterior.status})`;
  }
  else {
    const min = Math.min(...tecs.map(t => carga[b][String(t)] || 0));
    sorteio = tecs.map(String).filter(t => (carga[b][t] || 0) === min);
    escolhido = sorteio[Math.floor(Math.random() * sorteio.length)];
    regra = `condominio ${cond} — menor carga` + (sorteio.length > 1 ? ' (sorteio)' : '');
  }
  daRodada[b + '|' + p.id_cliente] = escolhido;
  const snap = Object.fromEntries(tecs.map(t => [t, carga[b][String(t)] || 0]));
  const antes = carga[b][escolhido] || 0;
  carga[b][escolhido] = antes + 1;
  resumo[b].encaminhar++;

  saida.push({ json: {
        ...base, condominio: cond, id_tecnico: Number(escolhido), id_setor: Number(idSetor), setor_origem: setorCfg ? 'SETOR do condomínio' : 'mantido da O.S.', regra,
    carga_antes: tecs.length > 1 ? snap : undefined,
    sorteado_entre: sorteio.length > 1 ? sorteio.map(Number) : undefined,
    modo: cfg.SIMULAR ? 'SIMULAÇÃO' : 'ENCAMINHAR',
    saida: cfg.SIMULAR ? NAO : SAIDA[b],
    payload: {
      id_chamado: String(p.id_chamado), alterar_setor: 'S', id_setor: idSetor, id_tecnico: String(escolhido), status: (cfg.MANTER_STATUS || []).includes(p.status) ? p.status : 'EN',
      mensagem: `Encaminhado automaticamente ao técnico do condomínio (${cond}).`,
      id_assunto: '', data: '', id_evento: '', latitude: '', longitude: '', gps_time: '', historico: '',
    },
  } });
});

return [
  { json: { tipo: 'panorama', saida: NAO, modo: cfg.SIMULAR ? 'SIMULAÇÃO' : 'ENCAMINHAR',
            filtro_status_na_api: cfg.FILTRO_STATUS_NA_API, resumo, carga_antes: cargaInicial, carga_depois: carga, leitura } },
  ...saida,
];

// Roda uma vez por O.S. encaminhada.
const d = $('Decidir').item.json;
let r = $json;
if (r && r.data !== undefined) {
  try { r = JSON.parse(String(r.data).replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '')); } catch (e) { r = { type: 'error', message: 'resposta ilegível: ' + String(r.data).slice(0, 200) }; }
}
const ok = !(r.error || r.type === 'error');
return { json: { base: d.base, id_chamado: d.id_chamado, condominio: d.condominio, id_tecnico: d.id_tecnico, regra: d.regra,
  ok, resposta: r.message || r.mensagem || (r.error ? JSON.stringify(r.error) : '') } };

// Nó "Msg Montar descrição" (Code, Run Once for All Items)
// Entrada: saídas dos 5 nós "Msg Ler OS <BASE>" (listar su_oss_chamado pelo id, lido DEPOIS do encaminhamento).
// Saída: 1 item por O.S. com o registro COMPLETO da O.S. e a descrição = descrição atual + Resposta Padrão.
// O PUT do IXC regrava o registro inteiro, por isso vai tudo como está e só a descrição muda.
// Se a descrição já contém o texto da Resposta Padrão, não acrescenta de novo.

function parseIxc(j) {
  let t = j?.data ?? j?.body ?? j;
  if (typeof t !== 'string') return t || {};
  t = t.replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '');
  try { return JSON.parse(t); } catch (e) { return { _texto: t }; }
}

// Texto comparável: sem HTML, sem acento de espaço/quebra, minúsculo.
function comparavel(s) {
  return String(s ?? '')
    .replace(/<\s*br\s*\/?>/gi, ' ').replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&')
    .replace(/\s+/g, ' ').trim().toLowerCase();
}

const temHtml = s => /<\s*(br|p|div|span|b|strong|ul|li)\b[^>]*>/i.test(String(s ?? ''));
const paraHtml = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\n/g, '<br>');

const out = [];
const itens = $input.all();
for (let i = 0; i < itens.length; i++) {
  const p = $('Msg Montar partes').itemMatching(i).json;
  const info = {
    base: p.base, saida: p.saida, destino: 'DESCRICAO', id_chamado: p.id_chamado, id_assunto: p.id_assunto,
    resposta_id: p.resposta_id, resposta_titulo: p.resposta_titulo, modo: p.modo, teste: p.teste,
    parte: 1, total_partes: 1, caracteres: p.caracteres,
  };
  const r = parseIxc(itens[i].json);

  if (r?.error || r?.type === 'error' || r?._texto !== undefined) {
    const det = r.error ? (r.error.message || JSON.stringify(r.error)) : (r.message || r._texto || '');
    out.push({ pairedItem: { item: i }, json: { ...info, pular: `erro ao ler a O.S.: ${String(det).slice(0, 200)}` } });
    continue;
  }
  const reg = Array.isArray(r?.registros) ? r.registros : [];
  const os = reg.find(x => String(x.id) === String(p.id_chamado));
  if (!os) {
    out.push({ pairedItem: { item: i }, json: { ...info, pular: `O.S. ${p.id_chamado} não encontrada na leitura` } });
    continue;
  }
  const campo = p.campo_descricao || 'mensagem';
  if (!(campo in os)) {
    out.push({ pairedItem: { item: i }, json: { ...info, pular: `campo "${campo}" não existe no su_oss_chamado (ajuste CAMPO_DESCRICAO)` } });
    continue;
  }

  const atual = String(os[campo] ?? '');
  if (comparavel(atual).includes(comparavel(p.texto))) {
    out.push({ pairedItem: { item: i }, json: { ...info, pular: 'descrição já tem esta Resposta Padrão (não acrescentou de novo)' } });
    continue;
  }

  let nova;
  if (!atual.trim()) nova = temHtml(atual) ? paraHtml(p.texto) : p.texto;
  else if (temHtml(atual)) nova = atual + '<br><br>' + paraHtml(p.texto);
  else nova = atual.replace(/\s+$/, '') + (p.separador ?? '\n\n') + p.texto;

  const put = { ...os, [campo]: nova };
  out.push({
    pairedItem: { item: i },
    json: {
      ...info, pular: '', enviar: p.modo === 'REAL',
      tamanho_antes: atual.length, tamanho_depois: nova.length,
      descricao_nova: nova,
      put_body: put,
    },
  });
}
return out;

// Nó "Msg Preparar" (Code, Run Once for All Items)
// Workflow: IXC - Encaminhar OS por condominio GLOBAL — bloco "Mensagem por assunto".
// Entrada: saídas dos 5 nós "Encaminhar <BASE>" (resposta do su_oss_chamado_alterar_setor).
// Saída: 1 item por O.S. encaminhada COM SUCESSO, já com a resposta padrão do assunto
//        e o destino: MENSAGEM nova no histórico ou ACRESCENTAR na descrição da O.S.
// Este nó não altera nada no IXC. Se algo falhar aqui, o encaminhamento já foi feito.

// ======================= CONFIGURAÇÃO =======================
// MODO: 'REAL'      -> grava na O.S. (mensagem ou descrição)
//       'SIMULAR'   -> só mostra no Resultado o texto e as partes (não grava)
//       'DESLIGADO' -> não faz nada
const MODO = 'REAL';

// Divisão da mensagem: 0 = mensagem inteira, numa só (padrão — o IXC aceita o texto todo,
// igual a quando se escolhe a Resposta Padrão na tela).
// Um número > 0 divide em partes desse tamanho: (1/3), (2/3)... (só se um dia precisar).
const TAM_PARTE = 0;

// id_evento exigido pelo su_oss_chamado_mensagem, por base. '' = vazio.
// Se o IXC recusar com erro de evento, preencha com o id do evento "Mensagem" da base.
const ID_EVENTO = { RESOLUTTO: '9', '4B': '', PONTO: '', CACTA: '', BUZZ: '' };

// Mandar o id_tecnico junto (mantém o técnico que o Encaminhar acabou de definir).
const ENVIAR_ID_TECNICO = true;

// Mandar o id da resposta padrão na 1ª parte (fica registrado qual resposta foi usada).
// Se o IXC duplicar o texto ou recusar por causa dela, mude para false.
const ENVIAR_ID_RESPOSTA = true;

// Assunto -> Resposta Padrão, POR BASE (os ids mudam de base para base!).
// Valor: número = id da resposta padrão; texto = título exato da resposta padrão.
// null = assunto sem mensagem extra.
const RESPOSTAS = {
  RESOLUTTO: { 69: 1, 83: 2, 84: 3, 86: null, 94: null },
  '4B':      { 89: null, 90: null, 91: null, 93: null, 98: null },
  PONTO:     { 65: null, 63: null, 62: null, 61: null, 70: null },
  CACTA:     { 73: null, 74: null, 77: null, 75: null, 81: null },
  BUZZ:      { 83: null, 84: null, 85: null, 87: null, 91: null },
};

// Onde a Resposta Padrão entra, POR BASE:
//   assuntos listados aqui -> ACRESCENTA no fim da DESCRIÇÃO da O.S. (não apaga nada do que já existe)
//   demais assuntos        -> MENSAGEM nova no histórico da O.S. (hoje: o 1º assunto da cadeia)
// Confira se a ordem bate com a cadeia (1º = Levantamento de Necessidades).
const NA_DESCRICAO = {
  RESOLUTTO: [83, 84, 86, 94],
  '4B':      [90, 91, 93, 98],
  PONTO:     [63, 62, 61, 70],
  CACTA:     [74, 77, 75, 81],
  BUZZ:      [84, 85, 87, 91],
};
// Campo da descrição no su_oss_chamado e o que separa o texto antigo do novo.
const CAMPO_DESCRICAO = 'mensagem';
const SEPARADOR = '\n\n';

// TESTE: só vale em execução MANUAL (botão "Execute workflow"). Nunca roda no agendamento.
// Para testar sem encaminhar nada: deixe SIMULAR = true no nó Config do Encaminhar,
// ligue o "Executar manualmente" também a este nó, preencha abaixo e execute.
const TESTE = { ativo: false, base: 'RESOLUTTO', id_chamado: '', id_assunto: '', id_tecnico: '', status: 'EN' };
// ============================================================

const BASES = ['RESOLUTTO', '4B', 'PONTO', 'CACTA', 'BUZZ']; // mesma ordem do Rotear por base (saída 0..4)

function normBase(v) {
  const s = String(v ?? '').toUpperCase();
  if (!s) return '';
  if (s.includes('4B')) return '4B';
  return BASES.find(b => s.includes(b)) || '';
}

// Procura uma chave em profundidade (até 3 níveis), ex.: id_chamado dentro de payload/body/os.
function achar(obj, nomes, prof = 0) {
  if (!obj || typeof obj !== 'object' || prof > 3) return undefined;
  for (const n of nomes) {
    if (obj[n] !== undefined && obj[n] !== null && obj[n] !== '') return obj[n];
  }
  for (const v of Object.values(obj)) {
    if (v && typeof v === 'object') {
      const r = achar(v, nomes, prof + 1);
      if (r !== undefined) return r;
    }
  }
  return undefined;
}

// Resposta do IXC pode vir em texto com caracteres de controle.
function parseIxc(j) {
  let t = j?.data ?? j?.body ?? j;
  if (typeof t !== 'string') return t || {};
  t = t.replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '');
  try { return JSON.parse(t); } catch (e) { return { _texto: t }; }
}

function encaminhouOk(r) {
  if (!r || typeof r !== 'object') return false;
  if (r.error) return false; // falha de rede/HTTP (onError: continue)
  if (String(r.type || '').toLowerCase() === 'error') return false;
  if (r._texto !== undefined) return !/"?type"?\s*:\s*"?error/i.test(r._texto) && r._texto.trim() !== '';
  return String(r.type || '').toLowerCase() === 'success' || r.id !== undefined || Object.keys(r).length > 0;
}

// Dicionário id da O.S. -> assunto, a partir do nó Pendentes (plano B se o Decidir não trouxer o assunto).
let assuntoPorOs = null;
function assuntoDoPendentes(base, id) {
  if (!assuntoPorOs) {
    assuntoPorOs = {};
    try {
      for (const it of $('Pendentes').all()) {
        const j = it.json || {};
        const b = normBase(achar(j, ['base', 'BASE']));
        const os = achar(j, ['id_chamado', 'id_os', 'id']);
        const as = achar(j, ['id_assunto']);
        if (os !== undefined && as !== undefined) assuntoPorOs[`${b}|${os}`] = as;
      }
    } catch (e) { /* nó Pendentes sem dados */ }
  }
  return assuntoPorOs[`${base}|${id}`] ?? assuntoPorOs[`|${id}`];
}

// Técnico escolhido pelo Decidir (o id_tecnico "cru" da O.S. pendente é 0, então tem prioridade o do payload).
function tecnicoFinal(dec) {
  const cands = [
    achar(dec?.payload || dec?.body || dec?.encaminhar || {}, ['id_tecnico']),
    achar(dec, ['id_tecnico_novo', 'tecnico_escolhido', 'id_tecnico_destino', 'tecnico_destino']),
    achar(dec, ['id_tecnico']),
  ];
  const t = cands.find(v => v !== undefined && String(v) !== '0' && String(v) !== '');
  return t !== undefined ? String(t) : '';
}

function statusFinal(dec) {
  const env = achar(dec?.payload || dec?.body || dec?.encaminhar || {}, ['status'])
           ?? achar(dec, ['status_enviar', 'status_novo', 'status']);
  return String(env ?? '').toUpperCase() === 'AG' ? 'AG' : 'EN';
}


function montar(j) {
  const base = normBase(j.base);
  const assunto = String(j.id_assunto ?? '').trim();
  const r = {
    base,
    saida: BASES.indexOf(base),
    id_chamado: String(j.id_chamado ?? '').trim(),
    id_assunto: assunto,
    id_tecnico: String(j.id_tecnico ?? '').trim(),
    status: String(j.status ?? 'EN').toUpperCase() === 'AG' ? 'AG' : 'EN',
    modo: MODO,
    tam_parte: TAM_PARTE,
    id_evento: ID_EVENTO[base] ?? '',
    enviar_id_tecnico: ENVIAR_ID_TECNICO,
    enviar_id_resposta: ENVIAR_ID_RESPOSTA,
    teste: j.teste === true,
    destino: (NA_DESCRICAO[base] || []).map(String).includes(assunto) ? 'DESCRICAO' : 'MENSAGEM',
    campo_descricao: CAMPO_DESCRICAO,
    separador: SEPARADOR,
    pular: '',
  };
  const ref = base ? (RESPOSTAS[base] || {})[assunto] : undefined;
  if (MODO === 'DESLIGADO') r.pular = 'MODO DESLIGADO';
  else if (!base) r.pular = `base não reconhecida (${j.base ?? 'vazia'})`;
  else if (!/^\d+$/.test(r.id_chamado)) r.pular = 'sem id_chamado';
  else if (!assunto) r.pular = 'sem id_assunto';
  else if (ref === undefined || ref === null || ref === '') r.pular = `assunto ${assunto} sem resposta padrão configurada em ${base}`;
  if (!r.pular) {
    const porId = typeof ref === 'number' || /^\d+$/.test(String(ref));
    r.resp_qtype = porId ? 'su_oss_respostas.id' : 'su_oss_respostas.titulo';
    r.resp_query = String(ref);
  }
  return r;
}

const modoExec = (typeof $execution !== 'undefined' && $execution) ? $execution.mode : '';
const saida = [];
const itens = $input.all();
for (let i = 0; i < itens.length; i++) {
  const j0 = itens[i].json || {};

  // Item que não veio de um "Encaminhar <BASE>" (ex.: gatilho manual ligado para teste).
  if (j0.data === undefined && j0.error === undefined && j0.body === undefined) {
    if (TESTE.ativo && modoExec !== 'production') {
      saida.push({ json: montar({ ...TESTE, teste: true }), pairedItem: { item: i } });
    }
    continue;
  }

  const resp = parseIxc(j0);
  if (!encaminhouOk(resp)) continue; // encaminhamento falhou: não grava mensagem

  let dec = {};
  try { dec = $('Rotear por base').itemMatching(i).json; }
  catch (e) { try { dec = $('Decidir').itemMatching(i).json; } catch (e2) { dec = {}; } }

  let base = normBase(achar(dec, ['base', 'BASE', 'nome_base']));
  if (!base) {
    const s = Number(achar(dec, ['saida']));
    if (Number.isInteger(s) && s >= 0 && s < BASES.length) base = BASES[s];
  }
  const idChamado = achar(dec, ['id_chamado', 'id_os', 'os_id']);
  let idAssunto = achar(dec, ['id_assunto', 'assunto']);
  if (idAssunto === undefined && idChamado !== undefined) idAssunto = assuntoDoPendentes(base, idChamado);

  saida.push({
    json: montar({
      base,
      id_chamado: idChamado !== undefined ? String(idChamado) : '',
      id_assunto: idAssunto !== undefined ? String(idAssunto) : '',
      id_tecnico: tecnicoFinal(dec),
      status: statusFinal(dec),
    }),
    pairedItem: { item: i },
  });
}
return saida;

// Nó "Msg Montar partes" (Code, Run Once for All Items)
// Entrada: saídas dos 5 nós "Msg Ler <BASE>" (listar su_oss_respostas).
// Saída: MENSAGEM -> 1 item por parte, com o payload do su_oss_chamado_mensagem (rota 0..4).
//        DESCRICAO -> 1 item com o texto a acrescentar (rota 5..9).

function parseIxc(j) {
  let t = j?.data ?? j?.body ?? j;
  if (typeof t !== 'string') return t || {};
  t = t.replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '');
  try { return JSON.parse(t); } catch (e) { return { _texto: t }; }
}

// Resposta padrão pode ter HTML (editor do IXC). Vira texto simples, mantendo as quebras de linha.
function textoLimpo(s) {
  return String(s ?? '')
    .replace(/\r\n?/g, '\n')
    .replace(/<\s*br\s*\/?>/gi, '\n')
    .replace(/<\/\s*(p|div|li|h[1-6])\s*>/gi, '\n')
    .replace(/<\s*li[^>]*>/gi, '- ')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&').replace(/&lt;/gi, '<').replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"').replace(/&#0?39;/gi, "'")
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

// Quebra o texto em pedaços de até `max` caracteres, preferindo cortar em
// quebra de linha, depois em espaço. Nunca perde caractere.
function quebrar(texto, max) {
  const partes = [];
  let resto = texto;
  while (resto.length > max) {
    let corte = resto.lastIndexOf('\n', max);
    if (corte < max * 0.5) corte = resto.lastIndexOf(' ', max);
    if (corte < max * 0.5) corte = max; // palavra gigante: corta seco
    partes.push(resto.slice(0, corte).trim());
    resto = resto.slice(corte).trim();
  }
  if (resto) partes.push(resto);
  return partes.filter(p => p.length);
}

function dividir(texto, tam) {
  if (texto.length <= tam) return [texto];
  // Reserva espaço para o prefixo "(nn/nn) " e recalcula se o total passar de 9.
  let reserva = 6, partes = [];
  for (let k = 0; k < 3; k++) {
    partes = quebrar(texto, Math.max(20, tam - reserva));
    const pref = `(${partes.length}/${partes.length}) `.length;
    if (pref <= reserva) break;
    reserva = pref;
  }
  return partes.map((p, i) => `(${i + 1}/${partes.length}) ${p}`);
}

const out = [];
const itens = $input.all();
for (let i = 0; i < itens.length; i++) {
  const cfg = $('Msg Preparar').itemMatching(i).json;
  const base = { ...cfg };
  const r = parseIxc(itens[i].json);

  if (r?.error || r?.type === 'error' || (r?._texto !== undefined)) {
    const det = r.error ? (r.error.message || JSON.stringify(r.error)) : (r.message || r._texto || '');
    out.push({ pairedItem: { item: i }, json: { ...base, enviar: false, pular: `erro ao ler resposta padrão: ${String(det).slice(0, 200)}` } });
    continue;
  }
  const reg = Array.isArray(r?.registros) ? r.registros : [];
  if (!reg.length) {
    out.push({ pairedItem: { item: i }, json: { ...base, enviar: false, pular: `resposta padrão "${cfg.resp_query}" não encontrada em ${cfg.base}` } });
    continue;
  }
  const rp = reg[0];
  const texto = textoLimpo(rp.resposta ?? rp.texto ?? rp.mensagem ?? '');
  if (!texto) {
    out.push({ pairedItem: { item: i }, json: { ...base, enviar: false, pular: `resposta padrão ${rp.id} está vazia` } });
    continue;
  }

  // Destino DESCRIÇÃO: 1 item com o texto inteiro; a leitura da O.S. e o acréscimo
  // são feitos depois (Msg Ler OS <BASE> -> Msg Montar descrição -> Msg Descrição <BASE>).
  if (cfg.destino === 'DESCRICAO') {
    out.push({
      pairedItem: { item: i },
      json: {
        base: cfg.base, saida: cfg.saida, rota: 5 + Number(cfg.saida), destino: 'DESCRICAO',
        id_chamado: cfg.id_chamado, id_assunto: cfg.id_assunto,
        resposta_id: String(rp.id ?? ''), resposta_titulo: String(rp.titulo ?? '').trim(),
        parte: 1, total_partes: 1, caracteres: texto.length,
        // enviar=true só leva à LEITURA da O.S. (inofensiva); o PUT é decidido no Msg Montar descrição.
        modo: cfg.modo, teste: cfg.teste, enviar: true, pular: '',
        texto, campo_descricao: cfg.campo_descricao || 'mensagem', separador: cfg.separador ?? '\n\n',
      },
    });
    continue;
  }

  const partes = Number(cfg.tam_parte) > 0 ? dividir(texto, Number(cfg.tam_parte)) : [texto];
  partes.forEach((p, k) => {
    const payload = {
      id_chamado: cfg.id_chamado,
      status: cfg.status,
      id_evento: cfg.id_evento ?? '',
      mensagem: p,
      // A resposta padrão vai só na 1ª parte; as demais são continuação.
      id_resposta: (k === 0 && cfg.enviar_id_resposta !== false) ? String(rp.id ?? '') : '',
    };
    if (cfg.enviar_id_tecnico && /^\d+$/.test(cfg.id_tecnico || '') && cfg.id_tecnico !== '0') {
      payload.id_tecnico = cfg.id_tecnico;
    }
    out.push({
      pairedItem: { item: i },
      json: {
        base: cfg.base,
        saida: cfg.saida,
        rota: Number(cfg.saida),
        destino: 'MENSAGEM',
        id_chamado: cfg.id_chamado,
        id_assunto: cfg.id_assunto,
        resposta_id: String(rp.id ?? ''),
        resposta_titulo: String(rp.titulo ?? '').trim(),
        parte: k + 1,
        total_partes: partes.length,
        caracteres: p.length,
        modo: cfg.modo,
        teste: cfg.teste,
        enviar: cfg.modo === 'REAL',
        pular: '',
        payload,
      },
    });
  });
}
return out;

// Nó "Msg Resultado" (Code, Run Once for All Items)
// Recebe: respostas dos "Msg Gravar <BASE>" (mensagem) e "Msg Descrição <BASE>" (PUT da O.S.),
// mais os itens simulados e pulados. Mostra 1 linha por O.S./parte. Não grava nada.

function parseIxc(j) {
  let t = j?.data ?? j?.body ?? j;
  if (typeof t !== 'string') return t || {};
  t = t.replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '');
  try { return JSON.parse(t); } catch (e) { return { _texto: t }; }
}

const out = [];
const itens = $input.all();
for (let i = 0; i < itens.length; i++) {
  const j = itens[i].json || {};

  // Item que não foi gravado (pulado ou simulado): já traz os campos.
  if (j.pular !== undefined || j.payload !== undefined) {
    out.push({ json: {
      base: j.base, id_chamado: j.id_chamado, id_assunto: j.id_assunto,
      destino: j.destino || '',
      parte: j.parte ? `${j.parte}/${j.total_partes}` : '',
      situacao: j.pular ? 'PULADO' : (j.modo === 'SIMULAR' ? 'SIMULADO' : 'NAO_ENVIADO'),
      motivo: j.pular || '',
      resposta_padrao: j.resposta_titulo ? `${j.resposta_id} - ${j.resposta_titulo}` : '',
      mensagem: j.payload?.mensagem ?? j.descricao_nova ?? j.texto ?? '',
      caracteres: j.caracteres ?? '',
    } });
    continue;
  }

  // Resposta do IXC a uma gravação real (mensagem ou descrição).
  let p = {};
  try { p = $('Msg Montar descrição').itemMatching(i).json; }
  catch (e) { try { p = $('Msg Montar partes').itemMatching(i).json; } catch (e2) { p = {}; } }
  const r = parseIxc(j);
  const erro = !!r?.error || r?.type === 'error' || (r?._texto !== undefined && /error/i.test(r._texto));
  out.push({ json: {
    base: p.base, id_chamado: p.id_chamado, id_assunto: p.id_assunto,
    destino: p.destino || '',
    parte: p.parte ? `${p.parte}/${p.total_partes}` : '',
    situacao: erro ? 'ERRO' : 'GRAVADO',
    motivo: erro ? String(r.error?.message || r.message || r._texto || '').slice(0, 300) : '',
    resposta_ixc: r?.id ?? r?.message ?? '',
    resposta_padrao: p.resposta_titulo ? `${p.resposta_id} - ${p.resposta_titulo}` : '',
    caracteres: p.destino === 'DESCRICAO' ? `${p.tamanho_antes} -> ${p.tamanho_depois}` : (p.caracteres ?? ''),
  } });
}
return out;
